?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Manajemen Perusahaan | SICERDAS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css" rel="stylesheet"><link href="../../assets/css/style.css" rel="stylesheet"></head><body><?php include __DIR__.'/../../layouts/sidebar.php';?><div class="main-wrapper"><?php include __DIR__.'/../../layouts/navbar.php';?><main class="content"><div class="page-heading"><div><p>Master Data</p><h1>Perusahaan</h1></div></div><div class="row g-3"><div class="col-lg-4"><div class="panel p-3"><h2 class="fs-6">Tambah Perusahaan</h2><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif?><form method="post" class="vstack gap-2"><input class="form-control" name="nama_perusahaan" placeholder="Nama perusahaan" required><textarea class="form-control" name="alamat" rows="2" placeholder="Alamat"></textarea><input class="form-control" name="telepon" placeholder="Telepon"><input type="email" class="form-control" name="email" placeholder="Email"><button class="btn btn-orange">Simpan</button></form></div></div><div class="col-lg-8"><div class="panel table-panel"><div class="table-responsive"><table class="table sicerdas-table"><thead><tr><th>Nama</th><th>Alamat</th><th>Telepon</th><th>Email</th></tr></thead><tbody><?php foreach($pdo->query('SELECT * FROM perusahaan ORDER BY nama_perusahaan') as $r):?><tr><td><?=htmlspecialchars($r['nama_perusahaan'])?></td><td><?=htmlspecialchars($r['alamat'])?></td><td><?=htmlspecialchars($r['telepon'])?></td><td><?=htmlspecialchars($r['email'])?></td></tr><?php endforeach?></tbody></table></div></div></div></div></main></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script></body></html>
